Dijkstra 最短路（堆优化）
int dis[N],vis[N];
vector <pii> G[N];
void dijkstra(int s){
    for(int i=1;i<=n;i++) dis[i]=INF;
    priority_queue <pii,vector<pii>,greater<pii>> q;
    dis[s]=0;
    q.push({0,s});
    while(!q.empty()){
        int u=q.top().second;
        q.pop();
        if(vis[u]) continue;
        vis[u]=1;
        for(auto g:G[u]){
            int v=g.first,w=g.second;
            if(dis[v]>dis[u]+w){
                dis[v]=dis[u]+w;
                q.push({dis[v],v});
            }
        }
    }
}

