Kruskal 最小生成树
struct Edge{ int u,v,w; }e[N];
bool cmp(Edge a,Edge b){ return a.w<b.w; }
int kruskal(){
    sort(e+1,e+m+1,cmp);
    for(int i=1;i<=n;i++) pa[i]=i;
    int cnt=0,ans=0;
    for(int i=1;i<=m;i++){
        int ru=find(e[i].u),rv=find(e[i].v);
        if(ru!=rv){
            pa[ru]=rv;
            ans+=e[i].w;
            cnt++;
        }
    }
    if(cnt==n-1) return ans;
    return -1;
}
